  1	import { ApiGatewayManagementApiClient, PostToConnectionCommand } from "@aws-sdk/client-apigatewaymanagementapi";
  2	import { DynamoDBClient } from "@aws-sdk/client-dynamodb";
  3	import { DeleteCommand, DynamoDBDocumentClient, PutCommand, QueryCommand } from "@aws-sdk/lib-dynamodb";
  4	import { traced } from "./xray.js";
  5	
  6	/**
  7	 * Who is listening, and telling them something changed.
  8	 *
  9	 * A device with a run open holds a WebSocket and says which session it is
 10	 * watching. When another device appends to that session, the API posts a
 11	 * one-line message down every socket watching it, "changed, seq 12",
 12	 * and the device syncs at once instead of at the next poll. The socket
 13	 * carries no data of its own: what changed still comes through the same
 14	 * authenticated HTTP fetch as before, so a socket that lies can only
 15	 * cause a fetch that finds nothing new.
 16	 *
 17	 * Three kinds of row, all short-lived. A connection, so a message from it
 18	 * can be tied to a person; a watch under the connection, so a disconnect
 19	 * can clean up; and a watch under the session, so a change can find its
 20	 * listeners in one query. Every row expires in two hours by TTL, because
 21	 * a disconnect that never arrives is a fact of life with sockets.
 22	 */
 23	
 24	const CONN_HOURS = 2;
 25	const expiresAfter = (at: string) => Math.floor(new Date(at).getTime() / 1000) + CONN_HOURS * 3600;
 26	
 27	/**
 28	 * A socket that is driving something rather than drawing something.
 29	 *
 30	 * A tool attached to a player's game is a watcher like any other, and is
 31	 * told what happened the same way; what differs is that it is sent
 32	 * operations rather than words, and that it may name which player it is
 33	 * so an effect meant for one of them reaches only that one.
 34	 */
 35	export interface Attached {
 36	  control?: boolean;
 37	  seat?: string;
 38	  /** What the tool called itself when it said hello. */
 39	  app?: string;
 40	  /** The run it was opened for, settled at connect.  */
 41	  run?: string;
 42	  /**
 43	   * A socket that presses rather than draws: a deck, signed in as the
 44	   * account, holding no run of its own. Marked so a press is never
 45	   * forwarded to one — two decks on one account must not look to each
 46	   * other like somewhere a press could land.
 47	   */
 48	  deck?: boolean;
 49	}
 50	
 51	export interface Watcher extends Attached {
 52	  connectionId: string;
 53	  sub: string;
 54	}
 55	
 56	export interface LiveStore {
 57	  connect(connectionId: string, sub: string, at: string, attached?: Attached): Promise<void>;
 58	  /** Who holds this connection, or null for one that was never accepted or has expired. */
 59	  connection(connectionId: string): Promise<({ sub: string } & Attached) | null>;
 60	  watch(connectionId: string, sessionId: string, sub: string, at: string, attached?: Attached): Promise<void>;
 61	  watchers(sessionId: string): Promise<Watcher[]>;
 62	  /** An account's deck connections, for news that is not about one run. */
 63	  decksOf(sub: string): Promise<Array<{ connectionId: string } & Attached>>;
 64	  /** The connection and every watch it held, gone. */
 65	  disconnect(connectionId: string): Promise<void>;
 66	}
 67	
 68	/** Only what was actually said, since a row of undefined is a row of nulls. */
 69	function marks(attached: Attached): Record<string, unknown> {
 70	  return {
 71	    ...(attached.control ? { control: true } : {}),
 72	    ...(attached.seat ? { seat: attached.seat } : {}),
 73	    ...(attached.app ? { app: attached.app } : {}),
 74	    ...(attached.run ? { run: attached.run } : {}),
 75	    ...(attached.deck ? { deck: true } : {}),
 76	  };
 77	}
 78	
 79	function read(row: Record<string, unknown>): Attached {
 80	  return {
 81	    ...(row["control"] === true ? { control: true as const } : {}),
 82	    ...(typeof row["seat"] === "string" ? { seat: row["seat"] } : {}),
 83	    ...(typeof row["app"] === "string" ? { app: row["app"] } : {}),
 84	    ...(typeof row["run"] === "string" ? { run: row["run"] } : {}),
 85	    ...(row["deck"] === true ? { deck: true as const } : {}),
 86	  };
 87	}
 88	
 89	export function dynamoLive({ table }: { table: string }): LiveStore {
 90	  const ddb = DynamoDBDocumentClient.from(traced(new DynamoDBClient({})), { marshallOptions: { removeUndefinedValues: true } });
 91	  const cpk = (id: string) => `CONN#${id}`;
 92	  const spk = (id: string) => `SESSION#${id}`;
 93	  const upk = (sub: string) => `USER#${sub}`;
 94	
 95	  return {
 96	    async connect(connectionId, sub, at, attached = {}) {
 97	      const expiresAt = expiresAfter(at);
 98	      const writes = [
 99	        ddb.send(
100	          new PutCommand({
101	            TableName: table,
102	            Item: { pk: cpk(connectionId), sk: "CONN", kind: "conn", sub, connectedAt: at, expiresAt, ...marks(attached) },
103	          }),
104	        ),
105	      ];
106	      // An account's decks, found in one query. A watch writes a row under
107	      // the session for the same reason; a deck holds no session yet.
108	      if (attached.deck)
109	        writes.push(
110	          ddb.send(
111	            new PutCommand({
112	              TableName: table,
113	              Item: { pk: upk(sub), sk: `DECK#${connectionId}`, kind: "deck", sub, expiresAt, ...marks(attached) },
114	            }),
115	          ),
116	        );
117	      await Promise.all(writes);
118	    },
119	    async connection(connectionId) {
120	      const out = await ddb.send(
121	        new QueryCommand({
122	          TableName: table,
123	          KeyConditionExpression: "pk = :pk AND sk = :sk",
124	          ExpressionAttributeValues: { ":pk": cpk(connectionId), ":sk": "CONN" },
125	        }),
126	      );
127	      const row = out.Items?.[0];
128	      if (!row || typeof row["sub"] !== "string") return null;
129	      if (typeof row["expiresAt"] === "number" && row["expiresAt"] * 1000 < Date.now()) return null;
130	      return { sub: row["sub"], ...read(row) };
131	    },
132	    async watch(connectionId, sessionId, sub, at, attached = {}) {
133	      const expiresAt = expiresAfter(at);
134	      await Promise.all([
135	        ddb.send(
136	          new PutCommand({
137	            TableName: table,
138	            Item: { pk: spk(sessionId), sk: `CONN#${connectionId}`, kind: "watch", sub, expiresAt, ...marks(attached) },
139	          }),
140	        ),
141	        ddb.send(
142	          new PutCommand({
143	            TableName: table,
144	            Item: { pk: cpk(connectionId), sk: `WATCH#${sessionId}`, kind: "watch", sub, expiresAt, ...marks(attached) },
145	          }),
146	        ),
147	      ]);
148	    },
149	    async watchers(sessionId) {
150	      const out = await ddb.send(
151	        new QueryCommand({
152	          TableName: table,
153	          KeyConditionExpression: "pk = :pk AND begins_with(sk, :sk)",
154	          ExpressionAttributeValues: { ":pk": spk(sessionId), ":sk": "CONN#" },
155	        }),
156	      );
157	      const now = Date.now() / 1000;
158	      return (out.Items ?? [])
159	        .filter((r) => typeof r["expiresAt"] !== "number" || r["expiresAt"] > now)
160	        .map((r) => ({ connectionId: String(r["sk"]).slice("CONN#".length), sub: String(r["sub"] ?? ""), ...read(r) }));
161	    },
162	    async decksOf(sub) {
163	      const out = await ddb.send(
164	        new QueryCommand({
165	          TableName: table,
166	          KeyConditionExpression: "pk = :pk AND begins_with(sk, :sk)",
167	          ExpressionAttributeValues: { ":pk": upk(sub), ":sk": "DECK#" },
168	        }),
169	      );
170	      const now = Date.now() / 1000;
171	      return (out.Items ?? [])
172	        .filter((r) => typeof r["expiresAt"] !== "number" || r["expiresAt"] > now)
173	        .map((r) => ({ connectionId: String(r["sk"]).slice("DECK#".length), ...read(r) }));
174	    },
175	    async disconnect(connectionId) {
176	      const out = await ddb.send(
177	        new QueryCommand({ TableName: table, KeyConditionExpression: "pk = :pk", ExpressionAttributeValues: { ":pk": cpk(connectionId) } }),
178	      );
179	      const rows = out.Items ?? [];
180	      await Promise.all(
181	        rows.flatMap((r) => {
182	          const sk = String(r["sk"]);
183	          const own = ddb.send(new DeleteCommand({ TableName: table, Key: { pk: cpk(connectionId), sk } }));
184	          if (sk === "CONN" && r["deck"] === true && typeof r["sub"] === "string")
185	            return [own, ddb.send(new DeleteCommand({ TableName: table, Key: { pk: upk(r["sub"]), sk: `DECK#${connectionId}` } }))];
186	          if (!sk.startsWith("WATCH#")) return [own];
187	          const sessionId = sk.slice("WATCH#".length);
188	          return [own, ddb.send(new DeleteCommand({ TableName: table, Key: { pk: spk(sessionId), sk: `CONN#${connectionId}` } }))];
189	        }),
190	      );
191	    },
192	  };
193	}
194	
195	/** What goes down a socket. One shape, so the app has one thing to parse. */
196	export interface Changed {
197	  t: "changed";
198	  id: string;
199	  seq: number;
200	}
201	
202	/** Something to tell the listeners of a session. Never throws: a failed nudge costs a poll, not a move. */
203	export type Notify = (sessionId: string, seq: number) => Promise<void>;
204	
205	/**
206	 * A gesture from the server rather than from a device: an ask arriving, an
207	 * ask answered. The same line a table's gesture takes down the socket, so
208	 * a listener has one shape to parse. Never throws, like a notify.
209	 */
210	export type Tell = (sessionId: string, kind: string, data: Record<string, unknown>, at: string) => Promise<void>;
211	
212	/** A way to post to one connection; the management API, or a test's list. */
213	export interface Poster {
214	  post(connectionId: string, data: string): Promise<"sent" | "gone">;
215	}
216	
217	export function apiGatewayPoster(endpoint: string): Poster {
218	  const client = new ApiGatewayManagementApiClient({ endpoint });
219	  return {
220	    async post(connectionId, data) {
221	      try {
222	        await client.send(new PostToConnectionCommand({ ConnectionId: connectionId, Data: data }));
223	        return "sent";
224	      } catch (error) {
225	        const e = error as { name?: string; $metadata?: { httpStatusCode?: number } };
226	        if (e.name === "GoneException" || e.$metadata?.httpStatusCode === 410) return "gone";
227	        throw error;
228	      }
229	    },
230	  };
231	}
232	
233	/**
234	 * The notifier the HTTP handler calls after a session changes. A
235	 * connection that is gone, closed without a disconnect the gateway told
236	 * us about, is cleaned up on the spot rather than left to the TTL.
237	 */
238	export function teller(live: LiveStore, poster: Poster): Tell {
239	  return async (sessionId, kind, data, at) => {
240	    try {
241	      const watchers = await live.watchers(sessionId);
242	      const line = JSON.stringify({ t: "gesture", id: sessionId, kind, data, at });
243	      await Promise.all(
244	        watchers.map(async (w) => {
245	          try {
246	            if ((await poster.post(w.connectionId, line)) === "gone") await live.disconnect(w.connectionId);
247	          } catch (error) {
248	            console.error("live: could not pass a line on", error);
249	          }
250	        }),
251	      );
252	    } catch (error) {
253	      console.error("live: could not tell", error);
254	    }
255	  };
256	}
257	
258	export function notifier(live: LiveStore, poster: Poster): Notify {
259	  return async (sessionId, seq) => {
260	    try {
261	      const watchers = await live.watchers(sessionId);
262	      const data = JSON.stringify({ t: "changed", id: sessionId, seq } satisfies Changed);
263	      await Promise.all(
264	        watchers.map(async (w) => {
265	          try {
266	            if ((await poster.post(w.connectionId, data)) === "gone") await live.disconnect(w.connectionId);
267	          } catch (error) {
268	            console.error("live: could not reach a connection", error);
269	          }
270	        }),
271	      );
272	    } catch (error) {
273	      console.error("live: could not notify", error);
274	    }
275	  };
276	}

