 71	/**
 72	 * A socket that presses rather than draws.
 73	 *
 74	 * It signs in as the account, the way the app's own devices do, because
 75	 * what it may do is what the owner may do. It names no run at connect: it
 76	 * is told which runs are being held, and picks. A link's token and a
 77	 * stream key are refused here, which is why this is read only on the
 78	 * signed-in branch below.
 79	 */
 80	function deckOf(event: WsEvent): { deck: true } | undefined {
 81	  return event.queryStringParameters?.["as"] === "deck" ? { deck: true } : undefined;
 82	}
 83	
 84	/**
 85	 * Whether this watcher is a device that could take a press.
 86	 *
 87	 * A link's socket and a scene's are not; an attached tool is told in
 88	 * operations and writes nothing; a deck is the thing asking. What is
 89	 * left is a signed-in device with the run open, which is the page.
 90	 */
 91	function writes(w: { sub: string; control?: boolean; deck?: boolean }): boolean {
 92	  return !w.control && !w.deck && !w.sub.startsWith("public:") && !w.sub.startsWith("stream:");
 93	}
