670	export async function handler(event: WsEvent): Promise<WsResult> {
671	  if (!deps) {
672	    const clientId = process.env["WORKOS_CLIENT_ID"] ?? "";
673	    const cliClientId = process.env["WORKOS_CLI_CLIENT_ID"] ?? "";
674	    const table = process.env["TABLE_NAME"] ?? "";
675	    const gates = process.env["RUNLOG_GATES"] === "on";
676	    const plusFeature = featuresFromEnv(process.env["STRIPE_FEATURES"]).plus;
677	    const billing = dynamoBilling({ table });
678	    deps = {
679	      live: dynamoLive({ table }),
680	      store: dynamoStore({ table, bucket: process.env["BUCKET_NAME"] ?? "" }),
681	      races: dynamoRaces({ table }),
682	      verify: (authorization) => verifyToken(authorization, [clientId, cliClientId]),
683	      ...(process.env["WS_ENDPOINT"] ? { poster: apiGatewayPoster(process.env["WS_ENDPOINT"]) } : {}),
684	      // No token flags are in hand at drive time, only `conn.sub`: the
685	      // kept flags `billing.flags(sub)` do the work a token flag would on
686	      // the API side, and `/api/me` refreshes those on every call the app
687	      // makes, so a comped account is comped here too.
688	      ...(gates ? { entitled: async (sub: string) => (await grantsOf(billing, sub)).includes(plusFeature) } : {}),
689	    };
690	  }
691	  try {
692	    return await route(event, deps);
693	  } catch (error) {
694	    console.error(error);
695	    return { statusCode: 500, body: "something went wrong on this side" };
696	  }
697	}
