36	export interface WsDeps {
37	  live: LiveStore;
38	  /** A way to post to connections; absent in a test that only checks routing. */
39	  poster?: Poster;
40	  store: Pick<Store, "getSession" | "streamKeyOwner" | "manifest" | "getSnapshot" | "addAsk" | "updateSession">;
41	  races: Pick<RaceStore, "getRace">;
42	  verify: (authorization: string | undefined) => Promise<Caller>;
43	  now?: () => string;
44	  /**
45	   * Whether this account may drive a run from outside it. Absent where
46	   * plans are off, which is the same answer as yes.
47	   */
48	  entitled?: (sub: string) => Promise<boolean>;
49	}
