291	
292	    // The table hears that somebody's game is on the other end of this.
293	    // Said here rather than at connect, because until the hello arrives
294	    // there is no seat and no name to say, and a row with neither is not
295	    // worth drawing.
296	    await tellWhoIsAttached(conn.run);
297	
298	    const poster = deps.poster;
299	    if (!poster) return { statusCode: 200 };
300	    const snapshot = await deps.store.getSnapshot(conn.run);
301	    const profile = snapshot ? profileOf(snapshot.snapshot) : null;
302	    // Told rather than left silent: a tool sitting there doing nothing
303	    // is the most confusing thing this could do. Which is what it did
304	    // until now in the one case that matters most, the run it found
305	    // having no rules at all: an address names an account and the
306	    // server picks the run, so a tool can attach perfectly to a run
307	    // nobody is playing and report itself connected for ever.
