     2	import { checklistOf, closesUnit } from "@runlog/engine";
     3	import { pointOf } from "./evidence.ts";
     4	
     5	/**
     6	 * What a deck may press, right now, in the pack's own words.
     7	 *
     8	 * The same reasoning as `snapshot.asks`: only a device holding the pack
     9	 * and the log can say what is on offer, so it is published rather than
    10	 * worked out by the server. Wider than `asks`, because a deck is the
    11	 * owner pressing and may do what the page's own buttons do.
    12	 *
    13	 * Deliberately conservative, for the reason `handsFree.ts` gives: this
    14	 * removes ceremony, never a decision. Anything the player is genuinely
    15	 * being asked, anything owed, and anything typed stops here and says so.
    16	 */
    17	export interface Offer {
    18	  seq: number;
    19	  primary: { id: "roll" | "carry-on" | "close" | "enter"; label: string; kind: string } | null;
    20	  moves: Array<{ id: string; label: string }>;
    21	  undo: { what: string } | null;
    22	  /** Why a deck cannot press this, in words a key face can carry. */
    23	  needsPage: string | null;
    24	  presets: Array<{ kind: string; label: string; suggestions?: string[]; items?: number }>;
    25	}
    26	
    27	export interface OfferInput {
    28	  /** The snapshot this offer belongs to; a press carries it back. */
    29	  seq: number;
    30	  /** Active, editable, and actually started. */
    31	  live: boolean;
    32	  /** Nothing more is being asked of this step. */
    33	  settled: boolean;
    34	  step: Step | null;
    35	  stepLabel: string | null;
    36	  moves: Array<{ id: string; label: string }>;
    37	  canUndo: boolean;
    38	  lastResult: string | null;
    39	  /** Obligations standing in the way. */
    40	  owed: number;
    41	  /** What the run would suggest for a subject, where it suggests anything. */
    42	  suggestions: string[];
    43	  /** What the page's between-units button says, or null when the run is not between units. */
    44	  between: string | null;
    45	  /**
    46	   * What the step's own button says once every box is ticked, or null
    47	   * where the step has no list. The preset presses that button, so it is
    48	   * offered in the words the page uses for it.
    49	   */
    50	  finishLabel: string | null;
    51	}
    52	
    53	/**
    54	 * Steps a key can answer with one press, because they ask nothing first.
    55	 *
    56	 * A step that closes the unit is not listed here: it is routed by
    57	 * `closesUnit` below, the same way whichever kind it is, rather than by
    58	 * its own kind.
    59	 */
    60	const PRESSABLE: Record<string, "roll" | "carry-on" | "close" | "enter"> = {
    61	  rollTable: "roll",
    62	};
    63	
    64	/** Steps that take something typed, and the preset that covers each. */
    65	const TYPED = new Set(["declareSubject"]);
    66	
    67	export function offerOf(input: OfferInput): Offer {
    68	  const moves = input.moves;
    69	  const undo = input.canUndo && input.lastResult ? { what: input.lastResult } : null;
    70	  const bare = { seq: input.seq, moves, undo, presets: [] as Offer["presets"] };
    71	
    72	  if (!input.live) return { ...bare, primary: null, needsPage: "Open the run on the page" };
    73	  if (!input.step) {
    74	    if (input.between) return { ...bare, primary: { id: "enter", label: input.between, kind: "between" }, needsPage: null };
    75	    return { ...bare, primary: null, needsPage: null };
    76	  }
    77	
    78	  const step = input.step;
    79	  const kind = step.kind;
    80	  const label = input.stepLabel ?? "";
    81	
    82	  // An unsettled step is still being asked something, the same reasoning
    83	  // `closesTheUnit` uses to refuse an unsettled unit: it is not yet a bare
    84	  // press for a key to make.
    85	  if (!input.settled) return { ...bare, primary: null, needsPage: `${label} on the page` };
    86	
    87	  if (TYPED.has(kind))
    88	    return {
    89	      ...bare,
    90	      primary: null,
    91	      needsPage: `${label} on the page`,
    92	      presets: [{ kind, label, ...(input.suggestions.length > 0 ? { suggestions: input.suggestions } : {}) }],
    93	    };
    94	
    95	  // Owed blocks every bare press but a typed step's own preset: the page
    96	  // would refuse the same close or carry-on until it is settled, checked
    97	  // once here rather than separately for every kind that reaches this far.
    98	  if (input.owed > 0) return { ...bare, primary: null, needsPage: "Something is owed; settle it on the page" };
    99	
   100	  /*
   101	   * Ticking the whole list and pressing the step's own button, for a key
   102	   * the streamer put there themselves.
   103	   *
   104	   * A preset, never the primary: `needsPage` stays, so the follow key goes
   105	   * on saying the list is on the page. Pressing this one skips the reading,
   106	   * which is a decision, and `handsFree.ts` gives the rule -- a decision is
   107	   * skipped only where somebody chose to skip it.
   108	   *
   109	   * The count is what the step waits for, which is its points less the
   110	   * optional ones. Not less the ones with nothing to show: that needs the
   111	   * log and the pack, and this says what is on offer from the step alone.
   112	   */
   113	  const list = checklistOf(step);
   114	  const ticking: Offer["presets"] =
   115	    list.length > 0 && input.finishLabel
   116	      ? [
   117	          {
   118	            kind: "checklist",
   119	            label: `Tick everything and ${input.finishLabel}`,
   120	            items: list.map(pointOf).filter((p) => !p.optional).length,
   121	          },
   122	        ]
   123	      : [];
