   125	  // A step that closes the unit goes to the page's closing card, whichever
   126	  // kind it is underneath: a finalizeUnit, or a manual step marked
   127	  // closesUnit. Its own confirmation or checklist is the same kind of ask
   128	  // as any other and sends it back to the page; empty, it is the one
   129	  // press that writes the close, not a step's own carry-on.
   130	  if (closesUnit(step)) {
   131	    if (list.length > 0) return { ...bare, primary: null, needsPage: `${label} on the page`, presets: ticking };
   132	    return { ...bare, primary: { id: "close", label, kind: step.kind }, needsPage: null };
   133	  }
   134	
   135	  // A manual step that does not close the unit asks nothing on its own; it
   136	  // only asks something when it carries a checklist to confirm. Empty, it
   137	  // is as bare a press as a roll.
   138	  if (step.kind === "manual") {
   139	    if (list.length > 0) return { ...bare, primary: null, needsPage: `${label} on the page`, presets: ticking };
   140	    return { ...bare, primary: { id: "carry-on", label, kind }, needsPage: null };
   141	  }
   142	
   143	  const id = PRESSABLE[kind];
   144	  if (!id) return { ...bare, primary: null, needsPage: `${label} on the page` };
   145	  return { ...bare, primary: { id, label, kind }, needsPage: null };
   146	}
