      async post(id, data) {
        posted.push([id, data]);
        return "sent";
      },
    };
    const d = { ...deps(live), poster, entitled: async () => false };
    await route(ev("$connect", "deck1", { queryStringParameters: { token: "good", as: "deck" } }), d);
    expect(posted.some(([, data]) => JSON.parse(data)["t"] === "runs")).toBe(true);
  });
});

