 1	/**
 2	 * A deck, in about forty lines, for anyone who has not got one.
 3	 *
 4	 * Signs in with the CLI's own saved session, renewing it if it is close to
 5	 * expiry the way `runlog`'s own `api()` does, then attaches as a deck,
 6	 * watches the run it is told is held, and presses the primary on it
 7	 * whenever Enter is struck. It is the smallest thing that exercises the
 8	 * whole path, and it is what the plugin will do.
 9	 */
10	import { credentials, renew } from "../packages/cli/src/account.ts";
11	
12	const RENEW_MARGIN_MS = 60_000;
13	// RUNLOG_WS=wss://runlog.dev.scrthq.com reaches the dev copy instead.
14	const base = process.env["RUNLOG_WS"] ?? "wss://runlog.scrthq.com";
15	
16	async function tokenFromSession(): Promise<string> {
17	  const override = process.argv[2];
18	  if (override) return override;
19	  const creds = credentials();
20	  if (creds?.session) {
21	    const lapsing = !creds.session.expiresAt || Date.parse(creds.session.expiresAt) - Date.now() < RENEW_MARGIN_MS;
22	    return lapsing ? (await renew(creds.session)).accessToken : creds.session.accessToken;
23	  }
24	  console.error("Run `npm run runlog -- login` first: the socket needs a signed-in session, not a key.");
25	  process.exit(1);
26	}
27	
28	const token = await tokenFromSession();
29	const ws = new WebSocket(`${base}/ws?token=${encodeURIComponent(token)}&as=deck`);
30	let run: string | null = null;
31	let seq = 0;
32	let connected = true;
33	
34	ws.addEventListener("close", () => {
35	  connected = false;
36	  console.log("socket closed");
37	});
38	ws.addEventListener("error", (event) => console.log((event as ErrorEvent).message ?? String(event)));
39	
40	ws.addEventListener("message", (event) => {
41	  const m = JSON.parse(String(event.data)) as Record<string, unknown>;
42	  if (m["t"] === "runs") {
43	    const runs = m["runs"] as Array<{ id: string; name?: string; packTitle?: string }>;
44	    console.log(runs.length === 0 ? "No run open." : runs.map((r) => `${r.id} ${r.name ?? ""} (${r.packTitle ?? ""})`).join("\n"));
45	    if (!run) {
46	      const picked = (process.env["RUN"] && runs.find((r) => r.id === process.env["RUN"])) || runs[0];
47	      run = picked?.id ?? null;
48	      if (run) ws.send(JSON.stringify({ t: "watch", id: run }));
49	    }
50	  }
51	  if (m["t"] === "changed" && m["id"] === run) seq = m["seq"] as number;
52	  if (m["t"] === "drove") console.log(m["ok"] ? "pressed" : `refused: ${String(m["say"] ?? "")}`);
53	});
54	
55	process.stdin.on("data", () => {
56	  if (!connected) return console.log("not connected");
57	  if (!run) return console.log("nothing to press");
58	  ws.send(
59	    JSON.stringify({
60	      t: "drive",
61	      run,
62	      seq: Number(process.env["SEQ"] ?? seq),
63	      ref: `cli-${Date.now()}`,
64	      press: "primary",
65	    }),
66	  );
67	});

