28	  const conns = new Map<string, string>();
29	  const watches = new Map<string, Set<string>>();
30	  const marks = new Map<string, Attached>();
31	  const watchMarks = new Map<string, Attached>();
32	  const watchedAt = new Map<string, string>();
33	  const watchKey = (sessionId: string, connectionId: string) => `${sessionId}|${connectionId}`;
34	  return {
35	    conns,
36	    watches,
37	    marks,
38	    watchMarks,
39	    async connect(id, sub, _at, attached) {
40	      conns.set(id, sub);
41	      if (attached) marks.set(id, attached);
42	    },
43	    async connection(id) {
44	      const sub = conns.get(id);
45	      return sub ? { sub, ...(marks.get(id) ?? {}) } : null;
46	    },
47	    async watch(id, sessionId, _sub, at, attached) {
48	      if (!watches.has(sessionId)) watches.set(sessionId, new Set());
49	      watches.get(sessionId)!.add(id);
50	      watchMarks.set(watchKey(sessionId, id), attached ?? {});
51	      watchedAt.set(watchKey(sessionId, id), at);
52	    },
53	    async watchers(sessionId): Promise<Watcher[]> {
54	      return [...(watches.get(sessionId) ?? [])].map((connectionId) => ({
